  function definition(u){const r=form();return {...r,...r.weapon,sourceUnit:'Hblm',hp:r.baseHp+r.strength*Number(rules.misc.StrHitPointBonus),art:r.model,role:'Intelligence / ranged',projectile:'blood-mage',spells:ids.map((_,i)=>spell(u,i)),splashEnemiesOnly:true};}
  function summonType(kind){const r=summon({kind});return {...r,...r.weapon,sourceUnit:kind==='phoenixegg'?'hpxe':'hphx',hp:r.baseHp,armor:r.armor==='small'?'light':r.armor==='large'?'heavy':r.armor,armorValue:r.baseArmor,food:0,flying:kind==='phoenix',flightHeight:Number(r.sourceRows.UnitData.moveHeight)/100,magicImmune:true,organic:true,projectile:'phoenix',splashEnemiesOnly:true,...(kind==='phoenix'?{splashBands:[[r.weapon.fullDamageRadius,1],[r.weapon.halfDamageRadius,r.weapon.splashHalf],[r.weapon.quarterDamageRadius,r.weapon.splashQuarter]]}:{})};}
  function reset(u,items){const old=u.maxHp;Object.assign(u,stats(u,items));if(u.hp>0)u.hp=Math.min(u.maxHp,Math.max(1,u.hp+u.maxHp-old));u.mana=Math.min(maxMana(u)*(1+rules.abilities.AHdr.levels[Math.max(0,(u.skills[2]||1)-1)].manaBonusFactor),u.mana);}
