    add(t?'#'+(triggerIndex+1)+' '+t.name:'New trigger',()=>{if(editMap.triggers.length){triggerIndex=(triggerIndex+1)%editMap.triggers.length;entryIndex=0;}else{editorTool='new';message('Click the map to place a trigger');}});
